#include "ImageAnnotations.h"

#include "Vault.h"

#include <QFileInfo>
#include <QRegularExpression>
#include <QStringList>

namespace noteAppC {

namespace {

const QString kBegin = QStringLiteral(
    "<!-- imageview:annotations:begin - generated by noteAppC, edits inside are replaced on the next save -->");
const QString kEnd = QStringLiteral("<!-- imageview:annotations:end -->");

// Four numbers at most five decimals each: a mark is placed to a fraction of
// a pixel on any image a screen can show, and a line stays short.
QString number(double value)
{
    QString text = QString::number(qBound(0.0, value, 1.0), 'f', 5);
    while (text.endsWith(QLatin1Char('0')) && !text.endsWith(QLatin1String(".0")))
        text.chop(1);
    return text;
}

QString kindName(ImageAnnotation::Kind kind)
{
    switch (kind) {
    case ImageAnnotation::Kind::Highlight:
        return QStringLiteral("highlight");
    case ImageAnnotation::Kind::Ink:
        return QStringLiteral("ink");
    case ImageAnnotation::Kind::Note:
        return QStringLiteral("note");
    }
    return {};
}

QList<double> numbersOf(const QString &text)
{
    QList<double> out;
    for (const QString &part : text.split(QRegularExpression(QStringLiteral("[,;]")), Qt::SkipEmptyParts)) {
        bool ok = false;
        const double value = part.toDouble(&ok);
        if (!ok)
            return {};
        out << qBound(0.0, value, 1.0);
    }
    return out;
}

const QRegularExpression &markerRe()
{
    static const QRegularExpression re(QStringLiteral("^%%\\s*image-annotation\\s+(.*?)\\s*%%\\s*$"));
    return re;
}

/// "key=value" words of a marker line.
QHash<QString, QString> fieldsOf(const QString &body)
{
    QHash<QString, QString> fields;
    for (const QString &word : body.split(QLatin1Char(' '), Qt::SkipEmptyParts)) {
        const qsizetype eq = word.indexOf(QLatin1Char('='));
        if (eq > 0)
            fields.insert(word.left(eq), word.mid(eq + 1));
    }
    return fields;
}

QString percent(double value)
{
    return QString::number(qRound(value * 100)) + QLatin1Char('%');
}

} // namespace

QRectF ImageAnnotation::bounds() const
{
    switch (kind) {
    case Kind::Highlight:
        return rect;
    case Kind::Ink:
        return stroke.boundingRect();
    case Kind::Note:
        return QRectF(point, QSizeF(0, 0));
    }
    return {};
}

bool operator==(const ImageAnnotation &a, const ImageAnnotation &b)
{
    return a.kind == b.kind && a.color == b.color && a.rect == b.rect && a.stroke == b.stroke
        && a.point == b.point && a.text == b.text;
}

QString ImageAnnotations::sidecarPath(const QString &imagePath)
{
    const QFileInfo info(imagePath);
    return info.absolutePath() + QLatin1Char('/') + info.fileName() + QStringLiteral(" annotations.md");
}

const QString &ImageAnnotations::beginMarker()
{
    return kBegin;
}

const QString &ImageAnnotations::endMarker()
{
    return kEnd;
}

const QList<QColor> &ImageAnnotations::palette()
{
    static const QList<QColor> colors = {QColor(0xFF, 0xEB, 0x3B), QColor(0x8B, 0xC3, 0x4A),
                                         QColor(0x4F, 0xC3, 0xF7), QColor(0xFF, 0x8A, 0x80),
                                         QColor(0xCE, 0x93, 0xD8)};
    return colors;
}

QList<ImageAnnotation> ImageAnnotations::parse(const QString &markdown)
{
    // Only the generated section: what the reader wrote around it is theirs.
    const qsizetype begin = markdown.indexOf(kBegin);
    const qsizetype end = markdown.indexOf(kEnd);
    if (begin < 0 || end < begin)
        return {};
    const QStringList lines = markdown.mid(begin + kBegin.size(), end - begin - kBegin.size())
                                  .split(QLatin1Char('\n'));
    QList<ImageAnnotation> out;
    for (qsizetype i = 0; i < lines.size(); ++i) {
        const QRegularExpressionMatch match = markerRe().match(lines.at(i));
        if (!match.hasMatch())
            continue;
        const QHash<QString, QString> fields = fieldsOf(match.captured(1));
        ImageAnnotation annotation;
        const QString kind = fields.value(QStringLiteral("kind"));
        if (const QColor color(fields.value(QStringLiteral("color"))); color.isValid())
            annotation.color = color;
        if (kind == QLatin1String("highlight")) {
            const QList<double> r = numbersOf(fields.value(QStringLiteral("rect")));
            if (r.size() != 4)
                continue;
            annotation.kind = ImageAnnotation::Kind::Highlight;
            annotation.rect = QRectF(r[0], r[1], r[2], r[3]);
        } else if (kind == QLatin1String("ink")) {
            const QList<double> p = numbersOf(fields.value(QStringLiteral("points")));
            if (p.size() < 4 || p.size() % 2)
                continue;
            annotation.kind = ImageAnnotation::Kind::Ink;
            for (qsizetype k = 0; k + 1 < p.size(); k += 2)
                annotation.stroke << QPointF(p[k], p[k + 1]);
        } else if (kind == QLatin1String("note")) {
            const QList<double> at = numbersOf(fields.value(QStringLiteral("at")));
            if (at.size() != 2)
                continue;
            annotation.kind = ImageAnnotation::Kind::Note;
            annotation.point = QPointF(at[0], at[1]);
        } else {
            continue;
        }

        // The text is everything under the marker up to the next entry's
        // boundary, trimmed of blank edges and otherwise as typed.
        QStringList text;
        for (qsizetype j = i + 1; j < lines.size(); ++j) {
            const QString trimmed = lines.at(j).trimmed();
            if (markerRe().match(lines.at(j)).hasMatch() || trimmed == QLatin1String("---"))
                break;
            const QString &line = lines.at(j);
            if (line.startsWith(QLatin1Char('\\'))
                && (line.mid(1).trimmed() == QLatin1String("---") || line.mid(1).startsWith(QLatin1String("%%"))))
                text << line.mid(1); // undo build()'s escape
            else
                text << line;
        }
        while (!text.isEmpty() && text.first().trimmed().isEmpty())
            text.removeFirst();
        while (!text.isEmpty() && text.last().trimmed().isEmpty())
            text.removeLast();
        annotation.text = text.join(QLatin1Char('\n'));
        out.append(annotation);
    }
    return out;
}

QString ImageAnnotations::build(const QList<ImageAnnotation> &annotations, const QString &imageFileName)
{
    QString out = QStringLiteral("![[%1]]\n").arg(imageFileName);
    for (const ImageAnnotation &a : annotations) {
        QString summary;
        QString fields = QStringLiteral("kind=%1 color=%2 ").arg(kindName(a.kind), a.color.name());
        switch (a.kind) {
        case ImageAnnotation::Kind::Highlight:
            summary = QStringLiteral("Highlight at %1, %2 (%3 by %4)")
                          .arg(percent(a.rect.x()), percent(a.rect.y()), percent(a.rect.width()),
                               percent(a.rect.height()));
            fields += QStringLiteral("rect=%1,%2,%3,%4")
                          .arg(number(a.rect.x()), number(a.rect.y()), number(a.rect.width()),
                               number(a.rect.height()));
            break;
        case ImageAnnotation::Kind::Ink: {
            QStringList points;
            for (const QPointF &p : a.stroke)
                points << number(p.x()) + QLatin1Char(',') + number(p.y());
            summary = QStringLiteral("Drawing at %1, %2 (%3 points)")
                          .arg(percent(a.stroke.boundingRect().x()), percent(a.stroke.boundingRect().y()))
                          .arg(a.stroke.size());
            fields += QStringLiteral("points=") + points.join(QLatin1Char(';'));
            break;
        }
        case ImageAnnotation::Kind::Note:
            summary = QStringLiteral("Note at %1, %2").arg(percent(a.point.x()), percent(a.point.y()));
            fields += QStringLiteral("at=%1,%2").arg(number(a.point.x()), number(a.point.y()));
            break;
        }
        out += QStringLiteral("\n> %1\n\n%% image-annotation %2 %%\n").arg(summary, fields);
        if (!a.text.isEmpty()) {
            // A line that would end the entry or look like a marker is escaped.
            QStringList lines = a.text.split(QLatin1Char('\n'));
            for (QString &line : lines) {
                if (line.trimmed() == QLatin1String("---") || line.startsWith(QLatin1String("%%")))
                    line.prepend(QLatin1Char('\\'));
            }
            const QString text = lines.join(QLatin1Char('\n'));
            out += text + QLatin1Char('\n');
        }
        out += QStringLiteral("\n---\n");
    }
    return out;
}

QString ImageAnnotations::merge(const QString &existing, const QString &generated)
{
    const QString section = kBegin + QLatin1Char('\n') + generated + kEnd;
    const qsizetype begin = existing.indexOf(kBegin);
    const qsizetype end = existing.indexOf(kEnd);
    if (begin < 0 || end < begin) {
        QString out = existing;
        if (!out.isEmpty() && !out.endsWith(QLatin1Char('\n')))
            out += QLatin1Char('\n');
        if (!out.isEmpty())
            out += QLatin1Char('\n');
        return out + section + QLatin1Char('\n');
    }
    return existing.left(begin) + section + existing.mid(end + kEnd.size());
}

QList<ImageAnnotation> ImageAnnotations::load(const QString &sidecarPath)
{
    Note note;
    if (!Vault::read(sidecarPath, note, nullptr))
        return {};
    return parse(note.text);
}

bool ImageAnnotations::save(const QString &sidecarPath, const QString &imageFileName,
                            const QList<ImageAnnotation> &annotations, QString *error)
{
    Note note; // a missing sidecar is the create half, not an error
    const bool existed = Vault::read(sidecarPath, note, nullptr);
    if (!existed && annotations.isEmpty())
        return true;
    note.text = merge(note.text, build(annotations, imageFileName));
    return Vault::write(sidecarPath, note, error);
}

} // namespace noteAppC
